mapper.select:
/* ReqInboxMapper.selectPendingRequests */ SELECT R.REQ_ID AS reqId , R.REQ_TYPE AS reqType , R.USER_CD AS userCd , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.USER_CD, null) AS userNm , R.SITE_CD AS siteCd , R.NODE_CD AS nodeCd , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'NODE', R.SITE_CD, R.NODE_CD) AS nodeNm , R.WORK_YMD AS workYmd , R.WORK_SEQ AS workSeq , R.START_DATE AS startDate , R.START_TIME AS startTime , R.END_DATE AS endDate , R.END_TIME AS endTime , R.OT_TYPE AS otType , R.REQ_REASON AS reqReason , DATE_FORMAT(R.INSERT_DATE, '%Y-%m-%dT%H:%i:%s') AS reqDate FROM TB_USER_ATTD_REQ R WHERE R.CMPNY_CD = #{cmpnyCd} AND R.SITE_CD = #{siteCd} AND R.REQ_STATUS = '01' AND R.DEL_YN = 'N' AND R.REQ_TYPE IN
#{rt}
ORDER BY R.INSERT_DATE DESC
